def parse_rating(v) -> Optional[int]:
    if v is None:
        raise HTTPException(422, "value is required")
    if isinstance(v, str):
        s = v.strip().lower()
        if s in RATING_WORDS:
            return RATING_WORDS[s]
        if s in ("0", "none", "clear", ""):
            return 0
        try:
            v = int(s)
        except ValueError:
            raise HTTPException(422, "value must be -1 (thumbs down), 1 (thumbs up), 2 (love) or 0 (clear)")
    if isinstance(v, bool) or not isinstance(v, (int, float)) or int(v) != v or int(v) not in (-1, 0, 1, 2):
        raise HTTPException(422, "value must be -1 (thumbs down), 1 (thumbs up), 2 (love) or 0 (clear)")
    return int(v)


