            ))}
          </div>
          {page < pages - 1 && (
            <button className="row-arrow right" aria-label={`Scroll ${title} right`} onClick={() => scrollBy(1)}>
              <Icon name="chevron-right" size={36} />
            </button>
          )}
        </div>
      )}
    </section>
  );
}
