@font-face { font-family: 'Anton'; font-style: normal; font-weight: 400; font-display: swap; src: url('/assets/fonts/display_anton_1.woff2') format('woff2'); unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF; }

:root {
  --bg: #141414;
  --red: #e50914;
  --red-hover: #c11119;
  --text: #fff;
  --muted: #808080;
  --muted2: #b3b3b3;
  --pad: 3.5vw;
  --gap: 8px;
  --ui: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  --display: 'Anton', 'Inter', Impact, sans-serif;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; background: var(--bg); color: var(--text); font-family: var(--ui); -webkit-font-smoothing: antialiased; }
body.modal-open { overflow: hidden; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; color: inherit; cursor: pointer; }
img { display: block; }
.muted { color: var(--muted); }
.small { font-size: 13px; }
.icon { display: inline-flex; align-items: center; justify-content: center; flex: none; line-height: 0; }
.icon svg { width: 100%; height: 100%; }
.dot { display: inline-block; width: 4px; height: 4px; border-radius: 50%; background: #646464; margin: 0 10px; vertical-align: middle; font-style: normal; }
.maturity { border: 1px solid rgba(255,255,255,.4); padding: 0 6px; font-size: .95em; line-height: 1.35; display: inline-block; }
.hd { border: 1px solid rgba(255,255,255,.4); border-radius: 3px; font-size: 11px; padding: 0 5px; line-height: 16px; font-weight: 600; }
.spinner { width: 48px; height: 48px; border: 3px solid rgba(255,255,255,.15); border-top-color: var(--red); border-radius: 50%; animation: spin 1s linear infinite; margin: 60px auto; }
@keyframes spin { to { transform: rotate(360deg); } }

/* ---------- buttons ---------- */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 12px; border: 0; border-radius: 4px; font-weight: 600; font-size: 22px; padding: 0 28px 0 22px; height: 56px; transition: background .15s; }
.btn.small { font-size: 16px; height: 42px; padding: 0 20px; }
.btn-play { background: #fff; color: #000; }
.btn-play:hover { background: rgba(255,255,255,.75); }
.btn-info { background: rgba(109,109,110,.7); color: #fff; }
.btn-info:hover { background: rgba(109,109,110,.4); }
.btn-red { background: var(--red); color: #fff; border: 0; border-radius: 4px; font-weight: 600; display: inline-flex; align-items: center; justify-content: center; gap: 10px; padding: 8px 18px; font-size: 16px; }
.btn-red:hover { background: var(--red-hover); }
.btn-red.small { font-size: 15px; padding: 7px 17px; font-weight: 700; }
.btn-red.big { font-size: 26px; padding: 0 26px; height: 62px; font-weight: 600; }
.btn-red.block { width: 100%; height: 54px; font-size: 19px; margin-top: 4px; }
.btn-red:disabled { opacity: .6; cursor: default; }
.btn-grey { background: rgba(128,128,128,.4); color: #fff; padding: 12px 18px; border-radius: 6px; font-weight: 600; font-size: 18px; }
.btn-grey:hover { background: rgba(128,128,128,.6); }
.btn-white { background: #fff; color: #000; border: 1px solid #fff; padding: 10px 24px; font-size: 18px; font-weight: 600; letter-spacing: 1px; }
.btn-white:hover { background: var(--red); color: #fff; border-color: var(--red); }
.btn-outline { background: transparent; color: var(--muted); border: 1px solid var(--muted); padding: 10px 24px; font-size: 18px; letter-spacing: 1px; display: inline-block; }
.btn-outline:hover { color: #fff; border-color: #fff; }
.wide { padding: 12px 32px; font-size: 20px; }
.link-btn { background: none; border: 0; color: var(--muted); font-size: 16px; margin-top: 16px; text-decoration: underline; }
.link-btn:hover { color: #fff; }
.circle-btn { width: 44px; height: 44px; border-radius: 50%; border: 2px solid rgba(255,255,255,.5); background: rgba(42,42,42,.6); color: #fff; display: inline-flex; align-items: center; justify-content: center; padding: 0; flex: none; transition: border-color .15s; }
.circle-btn:hover { border-color: #fff; }
.circle-btn.lg { width: 52px; height: 52px; }
.circle-btn.play { background: #fff; color: #000; border-color: #fff; }
.circle-btn.play:hover { background: rgba(255,255,255,.8); }
.circle-btn.rated { color: #fff; background: rgba(255,255,255,.18); }
.icon-btn { background: none; border: 0; color: #fff; padding: 4px; display: inline-flex; align-items: center; }

/* ---------- header ---------- */
.main-header { position: fixed; top: 0; left: 0; right: 0; z-index: 50; height: 88px; display: flex; align-items: center; padding: 0 var(--pad); background: linear-gradient(180deg, rgba(0,0,0,.7) 10%, transparent); transition: background .4s; }
.main-header.scrolled { background: var(--bg); }
.logo img { width: 84px; height: auto; margin-right: 28px; }
.primary-nav { display: flex; align-items: center; gap: 2px; }
.primary-nav a { font-size: 18px; color: #e5e5e5; padding: 11px 18px; border-radius: 22px; transition: color .3s, background .2s; white-space: nowrap; }
.primary-nav a:hover { color: #b3b3b3; }
.primary-nav a.active { background: rgba(255,255,255,.22); color: #fff; font-weight: 600; }
.secondary-nav { margin-left: auto; display: flex; align-items: center; gap: 22px; }
.search-box { display: flex; align-items: center; border: 1px solid transparent; transition: all .2s; height: 40px; }
.search-box.open { border-color: #fff; background: rgba(0,0,0,.75); padding-right: 6px; }
.search-box input { background: transparent; border: 0; outline: none; color: #fff; font-size: 15px; width: 220px; font-family: inherit; }
.search-box .clear { padding: 4px; }
.notif { position: relative; }
.notif-dot { position: absolute; top: 2px; right: 2px; width: 9px; height: 9px; background: var(--red); border-radius: 50%; }
.dropdown { position: absolute; right: 0; top: calc(100% + 14px); background: rgba(24,24,24,.97); border: 1px solid rgba(255,255,255,.12); border-radius: 8px; box-shadow: 0 8px 30px rgba(0,0,0,.6); z-index: 60; }
.notif-menu { width: 400px; max-height: 480px; overflow-y: auto; padding: 6px 0; }
.notif-item { display: flex; gap: 14px; width: 100%; background: none; border: 0; border-bottom: 1px solid rgba(255,255,255,.08); padding: 12px 16px; text-align: left; align-items: center; }
.notif-item:hover { background: rgba(255,255,255,.06); }
.notif-item img { width: 112px; height: 63px; object-fit: cover; border-radius: 4px; }
.notif-item > span { display: flex; flex-direction: column; gap: 3px; font-size: 14px; }
.notif-item small { color: var(--muted); }
.notif-empty { padding: 20px; color: var(--muted2); font-size: 14px; }
.kids-link { display: flex; align-items: center; gap: 10px; background: none; border: 0; font-size: 15px; color: #fff; padding: 0; }
.kids-link:hover span { text-decoration: underline; }
.account { position: relative; }
.account-btn { display: flex; align-items: center; gap: 10px; background: none; border: 0; padding: 0; }
.caret { width: 0; height: 0; border: 5px solid transparent; border-top-color: #fff; margin-top: 5px; transition: transform .25s; }
.caret.up { transform: rotate(180deg); margin-top: -5px; }
.account-menu { width: 278px; padding: 12px 0 6px; border-radius: 10px; top: calc(100% + 10px); }
.menu-item { display: flex; align-items: center; gap: 16px; width: 100%; background: none; border: 0; padding: 12px 18px; font-size: 17px; text-align: left; color: #fff; }
.menu-item:hover span, .menu-item.signout:hover { text-decoration: underline; }
.menu-sep { height: 1px; background: rgba(255,255,255,.15); margin: 6px 0; }
.menu-item.signout { padding: 14px 18px 16px; }

/* ---------- page shells ---------- */
.app-main { min-height: 100vh; }
.page { padding-bottom: 40px; }
.app-footer { padding: 30px var(--pad) 40px; color: var(--muted); font-size: 13px; max-width: 1100px; }
.footer-links { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 18px; }
.footer-links a:hover { text-decoration: underline; }
.toast { position: fixed; bottom: 30px; left: 50%; transform: translateX(-50%); background: #fff; color: #000; padding: 12px 22px; border-radius: 4px; font-weight: 600; z-index: 200; box-shadow: 0 6px 24px rgba(0,0,0,.5); }
.empty-hero { padding: 160px var(--pad) 40px; color: var(--muted2); font-size: 20px; }
.empty-page { padding: 160px var(--pad); text-align: center; }
.empty-page h1 { font-size: 56px; margin: 0 0 20px; }
.empty-page p { font-size: 22px; color: var(--muted2); margin-bottom: 30px; }
.empty-state { color: var(--muted2); font-size: 18px; padding: 40px 0; }
.empty-state ul { font-size: 15px; }
.page-title { font-size: 40px; font-weight: 400; margin: 0; padding: 0; }
.page-title.small { font-size: 22px; color: var(--muted2); }
.grid-page { padding: 104px var(--pad) 60px; min-height: 70vh; }
.grid-page .page-title { margin-bottom: 48px; }
.title-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 72px var(--gap); padding-top: 24px; }
.title-grid .title-card { width: auto; }

/* ---------- billboard ---------- */
.billboard { position: relative; overflow: hidden; background: #000; }
.billboard.inset { margin: 97px var(--pad) 0; border-radius: 16px; aspect-ratio: 1786 / 818; box-shadow: 0 10px 40px rgba(0,0,0,.6); }
.billboard.full { height: 56.25vw; max-height: 100vh; min-height: 520px; }
.billboard.skeleton { background: #222; }
.bb-media, .bb-media img, .bb-media video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.bb-media video { animation: fadein .8s ease; }
@keyframes fadein { from { opacity: 0; } to { opacity: 1; } }
.bb-shade { position: absolute; inset: 0; background: linear-gradient(77deg, rgba(0,0,0,.75) 0%, rgba(0,0,0,.25) 45%, transparent 70%); }
.billboard.full .bb-shade { background: linear-gradient(77deg, rgba(0,0,0,.6), transparent 85%), linear-gradient(180deg, transparent 70%, rgba(20,20,20,.6) 85%, var(--bg) 100%); }
.bb-content { position: absolute; left: 44px; bottom: 42px; width: 46%; z-index: 2; }
.billboard.full .bb-content { left: var(--pad); bottom: 30%; width: 40%; }
.bb-netflix { width: 92px; margin-bottom: 4px; }
.bb-title { font-family: var(--display); font-weight: 400; font-size: clamp(40px, 5.6vw, 110px); line-height: .95; margin: 0 0 18px; text-transform: uppercase; letter-spacing: .5px; text-shadow: 2px 2px 8px rgba(0,0,0,.45); }
.bb-rank { display: flex; align-items: center; gap: 14px; font-size: 28px; font-weight: 600; margin-bottom: 14px; }
.bb-meta { display: flex; align-items: center; font-size: 18px; font-weight: 500; margin-bottom: 26px; color: #fff; flex-wrap: wrap; }
.bb-synopsis { font-size: 22px; line-height: 1.35; margin: 0 0 24px; text-shadow: 2px 2px 4px rgba(0,0,0,.45); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.bb-buttons { display: flex; gap: 14px; }
.billboard.inset .btn { border-radius: 28px; height: 54px; font-size: 21px; padding: 0 24px 0 26px; }
.billboard.inset .btn-info { background: rgba(80,80,80,.6); }
.bb-side { position: absolute; right: 0; bottom: 30%; display: flex; align-items: center; gap: 14px; z-index: 2; }
.billboard.inset .bb-side { right: 44px; top: 44px; bottom: auto; }
.billboard.inset .bb-mute { width: 36px; height: 36px; border: 0; background: rgba(60,60,60,.8); }
.bb-maturity { background: rgba(51,51,51,.6); border-left: 3px solid #dcdcdc; padding: 8px 60px 8px 14px; font-size: 20px; }
.bb-new { position: absolute; right: 0; top: calc(818px * .56); }
.billboard.inset .bb-new { position: fixed; display: none; }
.top10-badge { display: inline-flex; flex-direction: column; align-items: center; justify-content: center; background: var(--red); color: #fff; font-weight: 800; font-size: 15px; line-height: .85; width: 28px; height: 38px; border-radius: 2px; letter-spacing: -.5px; }
.top10-badge small { font-size: 7.5px; letter-spacing: .3px; line-height: 1.2; }
.top10-badge.big { width: 42px; height: 48px; font-size: 21px; }
.top10-badge.big small { font-size: 10px; }

/* ---------- rows ---------- */
.rows { position: relative; z-index: 3; padding-top: 30px; }
.rows.overlap { margin-top: -10vw; }
.rows.top-pad { padding-top: 120px; }
.row { margin: 0 0 3.2vw; }
.row-head { display: flex; align-items: flex-end; justify-content: space-between; padding: 0 var(--pad); margin-bottom: 14px; }
.row-title { font-size: 28px; font-weight: 500; margin: 0; display: flex; align-items: center; gap: 12px; }
.row-title a .explore { font-size: 15px; color: #54b9c5; opacity: 0; transition: opacity .3s; margin-left: 6px; }
.row-title a:hover .explore { opacity: 1; }
.row-badge { border: 2px solid #b11ec1; border-radius: 5px; font-size: 13px; letter-spacing: 6px; padding: 3px 4px 3px 10px; font-weight: 700; }
.row-pages { display: flex; gap: 2px; }
.row-pages span { width: 14px; height: 2px; background: #4d4d4d; }
.row-pages span.on { background: #aaa; }
.row-wrap { position: relative; }
.row-scroller { display: flex; gap: var(--gap); overflow-x: auto; scroll-behavior: smooth; padding: 0 var(--pad); scroll-padding: 0 var(--pad); scrollbar-width: none; }
.row-scroller::-webkit-scrollbar { display: none; }
.row-arrow { position: absolute; top: 0; bottom: 0; width: calc(var(--pad) - 4px); z-index: 4; border: 0; background: rgba(20,20,20,.5); color: #fff; display: flex; align-items: center; justify-content: center; opacity: 0; transition: opacity .2s; }
.row-wrap:hover .row-arrow { opacity: 1; }
.row-arrow:hover { background: rgba(20,20,20,.75); }
.row-arrow.left { left: 0; }
.row-arrow.right { right: 0; }
.row-empty { padding: 0 var(--pad); color: var(--muted); font-size: 16px; margin: 0; }
.row-empty.big { font-size: 20px; padding: 20px var(--pad); }
.row-skeleton { display: flex; gap: var(--gap); padding: 14px var(--pad) 0; overflow: hidden; }
.row-skeleton div { flex: none; width: calc((100vw - 2 * var(--pad) - 5 * var(--gap)) / 6.1); aspect-ratio: 16/9; background: #222; border-radius: 4px; animation: pulse 1.2s infinite alternate; }
.row.loading .row-title { padding: 0 var(--pad); }
@keyframes pulse { from { opacity: .5; } to { opacity: 1; } }

.title-card { position: relative; flex: none; width: calc((100vw - 2 * var(--pad) - 5 * var(--gap)) / 6.1); }
.home .title-card.landscape { width: calc((100vw - 2 * var(--pad) - 4 * var(--gap)) / 5.1); }
.home .row-scroller .title-card.landscape .card-btn { border-radius: 8px; }
.card-btn { position: relative; display: block; width: 100%; aspect-ratio: 16/9; padding: 0; border: 0; border-radius: 4px; overflow: hidden; background: #222; }
.card-btn img { width: 100%; height: 100%; object-fit: cover; transition: transform .3s; }
.card-btn:focus-visible { outline: 3px solid #fff; }
.card-name { position: absolute; left: 10px; right: 30px; bottom: 26px; text-align: left; font-family: var(--display); font-size: clamp(16px, 1.45vw, 30px); line-height: 1; text-transform: uppercase; color: #fff; text-shadow: 0 2px 6px rgba(0,0,0,.85), 0 0 2px rgba(0,0,0,.6); }
.card-badge { position: absolute; bottom: 0; left: 50%; transform: translateX(-50%); background: var(--red); color: #fff; font-size: 13px; font-weight: 700; padding: 3px 8px; border-radius: 3px 3px 0 0; white-space: nowrap; }
.title-card .top10-badge { position: absolute; top: 0; right: 0; }
.card-progress { position: absolute; left: 10%; right: 10%; bottom: 8px; height: 3px; background: rgba(120,120,120,.8); }
.card-progress span { display: block; height: 100%; background: var(--red); }
.title-card.top10 { width: calc((100vw - 2 * var(--pad) - 5 * var(--gap)) / 6.1); display: flex; height: auto; }
.title-card.top10 .rank { width: 50%; flex: none; height: auto; overflow: visible; margin-right: -2px; }
.title-card.top10 .rank text { font-family: var(--ui); font-weight: 900; font-size: 172px; fill: #141414; stroke: #595959; stroke-width: 4px; letter-spacing: -14px; }
.title-card.top10 .card-btn { aspect-ratio: 2/3; width: 50%; border-radius: 2px; }
.title-card.portrait .card-btn { aspect-ratio: 2/3; }

/* hover preview (portal) */
.card-preview { position: absolute; z-index: 80; background: #181818; border-radius: 8px; overflow: hidden; box-shadow: 0 6px 24px rgba(0,0,0,.75); animation: grow .22s ease-out; cursor: pointer; }
@keyframes grow { from { transform: scale(.75); opacity: .3; } to { transform: scale(1); opacity: 1; } }
.cp-media { position: relative; aspect-ratio: 16/9; }
.cp-media img { width: 100%; height: 100%; object-fit: cover; }
.cp-media .cp-n { position: absolute; top: 14px; left: 14px; width: 22px; height: auto; }
.cp-name { position: absolute; left: 18px; right: 18px; bottom: 16px; font-family: var(--display); font-size: 34px; line-height: 1; text-transform: uppercase; text-shadow: 0 2px 8px rgba(0,0,0,.8); }
.cp-info { padding: 18px 18px 22px; cursor: default; }
.cp-buttons { display: flex; align-items: center; gap: 8px; margin-bottom: 18px; }
.cp-buttons .circle-btn { width: 52px; height: 52px; }
.cp-buttons .expand { margin-left: auto; }
.cp-meta { display: flex; align-items: center; gap: 10px; color: #bcbcbc; font-size: 18px; margin-bottom: 14px; }
.cp-meta .maturity { font-size: 18px; padding: 1px 8px; }
.cp-tags { font-size: 18px; display: flex; flex-wrap: wrap; align-items: center; }
.rate-picker { position: relative; }
.rate-options { display: flex; align-items: center; background: #2a2a2a; border-radius: 30px; padding: 4px; gap: 2px; box-shadow: 0 4px 14px rgba(0,0,0,.6); position: relative; }
.rate-opt { width: 46px; height: 46px; border-radius: 50%; border: 0; background: transparent; color: #fff; display: flex; align-items: center; justify-content: center; }
.rate-opt:hover { background: rgba(255,255,255,.12); }
.rate-opt.selected { background: rgba(255,255,255,.25); }
.rate-tip { position: absolute; bottom: calc(100% + 10px); left: 50%; transform: translateX(-50%); background: #e6e6e6; color: #000; font-size: 20px; font-weight: 500; padding: 8px 16px; border-radius: 4px; white-space: nowrap; }
.rate-tip::after { content: ''; position: absolute; top: 100%; left: 50%; margin-left: -8px; border: 8px solid transparent; border-top-color: #e6e6e6; }
.rate-picker.lg .rate-opt { width: 52px; height: 52px; }

/* ---------- sub headers (shows / movies / genre) ---------- */
.sub-header { position: absolute; top: 88px; left: 0; right: 0; z-index: 10; display: flex; align-items: center; gap: 50px; padding: 0 var(--pad); }
.sub-header h1 { font-size: 44px; font-weight: 500; margin: 0; }
.genres-menu { position: relative; }
.genres-btn { background: #000; border: 1px solid #fff; color: #fff; font-size: 18px; padding: 6px 12px; display: flex; align-items: center; gap: 36px; letter-spacing: .5px; }
.tri { width: 0; height: 0; border: 6px solid transparent; border-top-color: #fff; margin-top: 6px; display: inline-block; }
.genres-list { position: absolute; top: calc(100% + 2px); left: 0; background: rgba(0,0,0,.92); border: 1px solid rgba(255,255,255,.15); display: grid; grid-template-columns: repeat(3, max-content); grid-auto-flow: column; grid-template-rows: repeat(9, auto); gap: 0 32px; padding: 10px 12px; z-index: 20; }
.genres-list a { font-size: 16px; line-height: 29px; white-space: nowrap; }
.genres-list a:hover { text-decoration: underline; }
.genre-header { position: relative; z-index: 5; display: flex; align-items: center; gap: 14px; padding: 104px var(--pad) 18px; background: #000; }
.genre-header .crumb { color: var(--muted); font-size: 20px; }
.genre-header .crumb:hover { color: #fff; }
.crumb-sep { color: var(--muted); font-size: 22px; }
.genre-header h1 { font-size: 44px; font-weight: 500; margin: 0; }
.genre-bg { position: absolute; top: 166px; left: 0; right: 0; height: 60vh; background-size: cover; background-position: center; opacity: .35; mask-image: linear-gradient(180deg, #000 30%, transparent); -webkit-mask-image: linear-gradient(180deg, #000 30%, transparent); }
.genre-page { position: relative; }
.genre-rows { padding-top: 60px; }
.grid-section { padding: 0 var(--pad); }

/* ---------- games ---------- */
.games-hero { position: relative; height: 72vh; min-height: 480px; background: #222 center/cover; }
.games-shade { position: absolute; inset: 0; background: linear-gradient(77deg, rgba(0,0,0,.85), rgba(0,0,0,.2) 70%), linear-gradient(180deg, transparent 70%, var(--bg)); }
.games-content { position: absolute; left: var(--pad); bottom: 18%; max-width: 640px; }
.games-content h1 { font-family: var(--display); font-weight: 400; font-size: 96px; margin: 0 0 12px; text-transform: uppercase; line-height: 1; }
.games-empty { font-size: 20px; color: #ddd; margin: 0 0 24px; }

/* ---------- languages ---------- */
.lang-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 40px; }
.languages .page-title { margin-bottom: 0; }
.lang-prefs { display: flex; align-items: center; gap: 14px; font-size: 16px; }
.lang-dd { position: relative; }
.lang-dd-btn { background: #000; border: 1px solid #fff; color: #fff; font-size: 20px; padding: 4px 12px; min-width: 240px; display: flex; align-items: center; justify-content: space-between; letter-spacing: .5px; }
.lang-dd.wide .lang-dd-btn { min-width: 268px; }
.lang-dd-menu { position: absolute; top: 100%; left: 0; right: 0; background: rgba(0,0,0,.92); border: 1px solid rgba(255,255,255,.15); list-style: none; margin: 0; padding: 6px 0; z-index: 30; max-height: 70vh; overflow-y: auto; }
.lang-dd-menu button { background: none; border: 0; width: 100%; text-align: left; padding: 4px 12px; font-size: 16px; line-height: 21px; }
.lang-dd-menu button:hover { text-decoration: underline; }
.lang-dd-menu button[aria-selected="true"] { font-weight: 700; }

/* ---------- title modal ---------- */
.modal-backdrop { position: fixed; inset: 0; z-index: 100; background: rgba(0,0,0,.7); overflow-y: auto; display: flex; justify-content: center; padding: 36px 0; }
.title-modal { position: relative; width: min(1084px, 94vw); background: #181818; border-radius: 8px; overflow: hidden; height: max-content; box-shadow: 0 3px 20px rgba(0,0,0,.6); animation: modalin .25s ease-out; }
@keyframes modalin { from { transform: scale(.92); opacity: 0; } to { transform: scale(1); opacity: 1; } }
.modal-close { position: absolute; top: 18px; right: 18px; z-index: 5; width: 40px; height: 40px; border-radius: 50%; background: #181818; border: 0; color: #fff; display: flex; align-items: center; justify-content: center; }
.modal-loading, .modal-error { min-height: 400px; display: flex; align-items: center; justify-content: center; color: var(--muted2); }
.tm-hero { position: relative; aspect-ratio: 16/9; max-height: 610px; width: 100%; }
.tm-hero img, .tm-hero video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.tm-shade { position: absolute; inset: 0; background: linear-gradient(0deg, #181818 0%, transparent 45%); }
.tm-hero-content { position: absolute; left: 56px; right: 56px; bottom: 7%; }
.tm-title { font-family: var(--display); font-weight: 400; font-size: 64px; line-height: 1; margin: 0 0 30px; text-transform: uppercase; color: #fff; text-shadow: 2px 2px 8px rgba(0,0,0,.6); max-width: 70%; }
.tm-buttons { display: flex; align-items: center; gap: 10px; }
.tm-buttons .btn { height: 58px; font-size: 24px; padding: 0 34px 0 30px; }
.tm-mute { position: absolute; right: 0; bottom: 4px; background: transparent; }
.tm-body { padding: 0 56px 40px; }
.tm-info { display: grid; grid-template-columns: 2fr 1fr; gap: 40px; }
.tm-meta { display: flex; align-items: center; gap: 10px; color: #bcbcbc; font-size: 18px; margin-bottom: 6px; }
.tm-meta2 { display: flex; align-items: center; gap: 10px; font-size: 16px; margin-bottom: 16px; }
.tm-rank { display: flex; align-items: center; gap: 12px; font-size: 22px; font-weight: 600; margin-bottom: 14px; }
.tm-rank .top10-badge.big { width: 30px; height: 34px; font-size: 14px; }
.tm-rank .top10-badge.big small { font-size: 7px; }
.tm-synopsis { font-size: 18px; line-height: 1.6; margin: 18px 0 0; }
.tm-right p { font-size: 15px; line-height: 1.5; margin: 0 0 14px; }
.episodes { margin-top: 48px; }
.ep-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }
.ep-head h3, .more-like h3, .about h3 { font-size: 26px; font-weight: 500; margin: 0; }
.ep-series { font-size: 19px; }
.ep-season-meta { font-size: 15px; margin-bottom: 18px; display: flex; align-items: center; gap: 8px; }
.season-select { position: relative; }
.season-btn { background: #242424; border: 1px solid #4d4d4d; border-radius: 4px; color: #fff; font-size: 19px; padding: 10px 20px; display: flex; align-items: center; gap: 44px; }
.season-menu { position: absolute; right: 0; top: calc(100% + 4px); background: #242424; border: 1px solid #4d4d4d; list-style: none; margin: 0; padding: 6px 0; min-width: 100%; z-index: 5; }
.season-menu button { background: none; border: 0; padding: 10px 20px; width: 100%; text-align: left; font-size: 17px; }
.season-menu button:hover { background: #414141; }
.episode { display: flex; align-items: center; width: 100%; background: transparent; border: 0; border-bottom: 1px solid #404040; padding: 30px 32px; text-align: left; border-radius: 4px; color: #fff; }
.episode:first-of-type, .episode.current { background: #333; }
.episode:hover { background: #333; }
.ep-num { width: 50px; font-size: 26px; color: #d2d2d2; flex: none; }
.ep-thumb { position: relative; width: 170px; aspect-ratio: 16/9; flex: none; border-radius: 4px; overflow: hidden; margin-right: 18px; }
.ep-thumb img { width: 100%; height: 100%; object-fit: cover; }
.ep-play { position: absolute; inset: 0; margin: auto; width: 52px; height: 52px; border-radius: 50%; border: 1px solid #fff; background: rgba(30,30,30,.5); display: flex; align-items: center; justify-content: center; opacity: 0; transition: opacity .2s; }
.episode:hover .ep-play { opacity: 1; }
.ep-body { flex: 1; display: flex; flex-direction: column; gap: 8px; padding-right: 40px; }
.ep-title { display: flex; justify-content: space-between; font-size: 18px; }
.ep-syn { font-size: 15px; color: #d2d2d2; line-height: 1.45; }
.more-like { margin-top: 48px; }
.ml-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 20px; }
.ml-card { background: #2f2f2f; border-radius: 4px; overflow: hidden; }
.ml-media { position: relative; display: block; width: 100%; aspect-ratio: 16/9; border: 0; padding: 0; background: #000; }
.ml-media img { width: 100%; height: 100%; object-fit: cover; }
.ml-len { position: absolute; top: 8px; right: 10px; font-weight: 600; font-size: 15px; text-shadow: 0 1px 4px #000; }
.ml-play { position: absolute; inset: 0; margin: auto; width: 48px; height: 48px; border-radius: 50%; border: 1px solid #fff; background: rgba(30,30,30,.6); display: flex; align-items: center; justify-content: center; opacity: 0; transition: opacity .2s; }
.ml-card:hover .ml-play { opacity: 1; }
.ml-body { padding: 14px 16px 18px; }
.ml-row { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
.ml-name { font-weight: 600; font-size: 15px; margin-bottom: 6px; }
.ml-meta { color: #bcbcbc; font-size: 14px; display: flex; gap: 6px; align-items: center; }
.ml-body p { font-size: 14px; color: #d2d2d2; line-height: 1.45; margin: 12px 0 0; display: -webkit-box; -webkit-line-clamp: 5; -webkit-box-orient: vertical; overflow: hidden; }
.about { margin-top: 48px; padding-top: 10px; }
.about h3 { margin-bottom: 18px; font-weight: 400; }
.about p { font-size: 15px; margin: 0 0 10px; }

/* rate dialog */
.rate-dialog-backdrop { position: fixed; inset: 0; z-index: 150; background: rgba(0,0,0,.6); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); display: flex; align-items: center; justify-content: center; }
.rate-dialog { position: relative; width: min(960px, 92vw); text-align: center; padding: 30px 0 40px; }
.rd-line { height: 4px; background: var(--red); border-radius: 2px; margin-bottom: 14px; }
.rd-close { position: absolute; right: 14px; top: 26px; background: none; border: 0; color: #fff; }
.rate-dialog h2 { font-size: 48px; font-weight: 700; margin: 52px 0 18px; }
.rate-dialog p { font-size: 21px; color: #d6d6d6; margin: 0 0 54px; }
.rd-options { display: flex; justify-content: center; gap: 40px; }
.rd-opt { width: 230px; background: none; border: 2px solid transparent; border-radius: 10px; color: #fff; display: flex; flex-direction: column; align-items: center; gap: 22px; font-size: 17px; padding: 14px 10px; }
.rd-opt:hover { background: rgba(255,255,255,.06); }
.rd-opt.selected { border-color: #fff; background: rgba(255,255,255,.1); }
.rd-got { margin-top: 60px; background: rgba(30,30,30,.9); color: #fff; border: 0; border-radius: 4px; padding: 12px 26px; font-weight: 700; font-size: 17px; }
.rd-got:hover { background: #333; }

/* ---------- landing ---------- */
.landing { position: relative; min-height: 100vh; background: #000; overflow: hidden; }
.landing-collage { position: absolute; inset: 0 0 auto 0; height: 940px; overflow: hidden; }
.collage-grid { position: absolute; top: -260px; left: -260px; width: 2600px; display: grid; grid-template-columns: repeat(10, 240px); gap: 14px; transform: rotate(-13deg) skewX(8deg); transform-origin: center; }
.collage-grid img { width: 240px; height: 340px; object-fit: cover; border-radius: 8px; }
.landing-shade { position: absolute; inset: 0 0 auto 0; height: 940px; background: radial-gradient(ellipse at center, rgba(0,0,0,.55) 0%, rgba(0,0,0,.72) 70%), linear-gradient(180deg, rgba(0,0,0,.6) 0%, transparent 20%); }
.landing-header { position: relative; z-index: 2; display: flex; justify-content: space-between; align-items: center; padding: 22px 168px; }
.landing-logo { width: 166px; }
.landing-actions { display: flex; align-items: center; gap: 14px; }
.lang-select { display: flex; align-items: center; gap: 6px; border: 1px solid rgba(255,255,255,.5); border-radius: 4px; padding: 6px 12px; background: rgba(0,0,0,.5); color: #fff; }
.lang-select select { background: transparent; color: #fff; border: 0; font-size: 18px; font-family: inherit; outline: none; }
.lang-select option { color: #000; }
.landing-hero { position: relative; z-index: 2; text-align: center; padding: 200px 20px 0; max-width: 1100px; margin: 0 auto; height: 870px; }
.landing-hero h1 { font-size: 62px; font-weight: 900; line-height: 1.25; margin: 0 auto 26px; max-width: 680px; }
.landing-sub { font-size: 22px; font-weight: 600; margin: 0 0 34px; }
.landing-form p { font-size: 18px; margin: 0 0 18px; }
.landing-row { display: flex; gap: 10px; justify-content: center; }
.landing-row input { width: 408px; height: 62px; background: rgba(22,22,22,.7); border: 1px solid rgba(128,128,128,.7); border-radius: 4px; color: #fff; font-size: 18px; padding: 0 18px; font-family: inherit; }
.landing-curve { position: relative; z-index: 2; height: 100px; margin-top: -60px; background: radial-gradient(50% 500% at 50% -420%, rgba(64,97,231,.4) 80%, rgba(0,0,0,.1) 100%), #000; border-top: 4px solid; border-image: linear-gradient(90deg, rgba(33,13,22,1) 16%, rgba(184,40,105,1), rgba(229,9,20,1), rgba(184,40,105,1), rgba(33,13,22,1) 84%) 1; border-radius: 50% 50% 0 0 / 100% 100% 0 0; }
.landing-promo { position: relative; z-index: 2; background: #000; padding: 0 168px 60px; }
.promo-card { display: flex; align-items: center; gap: 30px; background: linear-gradient(149deg, #192247 0%, #210e17 96%); border-radius: 16px; padding: 18px 36px 18px 130px; position: relative; }
.popcorn { position: absolute; left: -100px; font-size: 76px; width: 120px; text-align: right; }
.promo-card > div { display: flex; flex-direction: column; gap: 4px; flex: 1; }
.promo-card b { font-size: 22px; }
.promo-card span { font-size: 17px; }

/* ---------- auth ---------- */
.auth-page { min-height: 100vh; display: flex; flex-direction: column; background: linear-gradient(180deg, #3b1617 0%, #1d0b0b 40%, #000 82%); }
.auth-header { padding: 22px 0 22px 213px; border-bottom: 1px solid rgba(255,255,255,.1); }
.auth-header img { width: 166px; }
.auth-main { flex: 1; display: flex; justify-content: center; padding: 40px 20px 80px; }
.auth-form { width: 490px; }
.auth-form h1 { font-size: 34px; font-weight: 700; margin: 0 0 8px; }
.auth-sub { font-size: 19px; color: #d3d3d3; margin: 0 0 26px; }
.auth-sub a { color: #d3d3d3; }
.auth-sub a:hover { text-decoration: underline; }
.float-field { display: block; position: relative; border: 1px solid rgba(128,128,128,.7); border-radius: 4px; background: rgba(22,22,22,.7); margin-bottom: 14px; padding: 8px 16px 6px; }
.float-field:focus-within { outline: 2px solid #fff; outline-offset: 1px; }
.float-field span { display: block; font-size: 13px; color: #c8c8c8; }
.float-field input { width: 100%; background: transparent; border: 0; outline: none; color: #fff; font-size: 18px; padding: 4px 0 4px; font-family: inherit; }
.auth-error { background: #d89d31; color: #000; padding: 12px 16px; border-radius: 4px; margin-bottom: 16px; font-size: 15px; }
.get-help { margin-top: 50px; background: none; border: 0; font-size: 18px; display: flex; align-items: center; gap: 6px; padding: 0; }
.help-panel { margin-top: 14px; color: #ddd; font-size: 15px; background: rgba(255,255,255,.06); padding: 12px 16px; border-radius: 4px; }
.help-panel a { text-decoration: underline; }
.auth-fine { font-size: 14px; color: #8c8c8c; margin-top: 50px; }
.auth-footer { background: #161616; padding: 60px 213px 60px; color: #b3b3b3; border-top: 1px solid #222; }
.auth-footer p { font-size: 18px; margin: 0 0 26px; }
.auth-footer-links { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
.auth-footer-links a { text-decoration: underline; font-size: 16px; }

/* ---------- profiles ---------- */
.profiles-page { min-height: 100vh; background: var(--bg); display: flex; flex-direction: column; }
.profiles-header { padding: 24px var(--pad); }
.profiles-header img { width: 120px; }
.profiles-center { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; padding-bottom: 80px; }
.profiles-center h1 { font-size: 56px; font-weight: 500; margin: 0 0 30px; }
.profile-grid { list-style: none; display: flex; gap: 32px; padding: 0; margin: 0 0 60px; flex-wrap: wrap; justify-content: center; }
.profile-tile { background: none; border: 0; display: flex; flex-direction: column; align-items: center; gap: 14px; color: var(--muted); font-size: 20px; }
.pt-avatar { position: relative; border: 3px solid transparent; border-radius: 8px; display: block; }
.profile-tile:hover .pt-avatar { border-color: #fff; }
.profile-tile:hover .pt-name { color: #fff; }
.pt-edit { position: absolute; inset: 0; background: rgba(0,0,0,.55); display: flex; align-items: center; justify-content: center; border-radius: 6px; }
.add-avatar { width: 156px; height: 156px; display: flex; align-items: center; justify-content: center; }
.profile-tile.add:hover .add-avatar { background: #e5e5e5; }
.profiles-actions { display: flex; flex-direction: column; align-items: center; }
.profile-form { max-width: 720px; margin: 120px auto; padding: 0 20px; width: 100%; }
.profile-form h1 { font-size: 56px; font-weight: 500; margin: 0 0 6px; }
.profile-form > p { font-size: 18px; margin: 0 0 20px; padding-bottom: 20px; border-bottom: 1px solid #333; }
.pf-row { display: flex; gap: 24px; padding-bottom: 24px; border-bottom: 1px solid #333; }
.pf-fields { flex: 1; display: flex; flex-direction: column; gap: 18px; }
.pf-fields > input { background: #666; border: 0; color: #fff; font-size: 18px; padding: 10px 12px; font-family: inherit; }
.pf-avatars { display: flex; gap: 10px; flex-wrap: wrap; }
.pf-avatars button { background: none; border: 2px solid transparent; border-radius: 6px; padding: 2px; }
.pf-avatars button.on { border-color: #fff; }
.pf-kids { display: flex; align-items: center; gap: 10px; font-size: 17px; }
.pf-kids input { width: 22px; height: 22px; accent-color: var(--red); }
.pf-actions { display: flex; gap: 18px; margin-top: 30px; }

/* ---------- account ---------- */
.account-page { padding: 120px var(--pad) 60px; max-width: 980px; }
.account-card { display: flex; flex-direction: column; gap: 30px; margin-top: 30px; }
.account-card section { border-top: 1px solid #333; padding-top: 18px; }
.account-card h2 { font-size: 20px; color: var(--muted2); font-weight: 500; margin: 0 0 12px; }
.account-card p { margin: 6px 0; font-size: 17px; }
.account-profiles { list-style: none; padding: 0; margin: 0 0 16px; display: flex; flex-direction: column; gap: 10px; }
.account-profiles li { display: flex; align-items: center; gap: 12px; font-size: 17px; }
.account-card .btn-red { align-self: flex-start; padding: 12px 22px; }

/* ---------- player ---------- */
.player { position: fixed; inset: 0; background: #000; z-index: 300; overflow: hidden; }
.player.hide { cursor: none; }
.player video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; background: #000; }
.player.error { display: flex; align-items: center; justify-content: center; color: var(--muted2); font-size: 20px; }
.pl-loading { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; }
.pl-top { position: absolute; top: 0; left: 0; right: 0; padding: 30px 36px; display: flex; justify-content: space-between; background: linear-gradient(180deg, rgba(0,0,0,.6), transparent); transition: opacity .3s; z-index: 2; }
.pl-back { position: absolute; top: 30px; left: 36px; background: none; border: 0; color: #fff; }
.pl-btn { background: none; border: 0; color: #fff; padding: 6px; display: inline-flex; align-items: center; justify-content: center; transition: transform .15s; }
.pl-btn:hover { transform: scale(1.2); }
.pl-btn .filled svg { fill: currentColor; }
.pl-bottom { position: absolute; left: 0; right: 0; bottom: 0; padding: 0 30px 26px; background: linear-gradient(0deg, rgba(0,0,0,.75), transparent); transition: opacity .3s; z-index: 2; }
.player.hide .pl-top, .player.hide .pl-bottom { opacity: 0; pointer-events: none; }
.pl-timeline { display: flex; align-items: center; gap: 18px; margin-bottom: 28px; }
.pl-track { position: relative; flex: 1; height: 4px; background: #5b5b5b; cursor: pointer; padding: 8px 0; background-clip: content-box; }
.pl-track:hover { padding: 7px 0; }
.pl-buffer, .pl-played { position: absolute; left: 0; top: 8px; height: 4px; }
.pl-buffer { background: #a3a3a3; }
.pl-played { background: var(--red); }
.pl-knob { position: absolute; top: 50%; width: 18px; height: 18px; margin: -9px 0 0 -9px; border-radius: 50%; background: var(--red); }
.pl-hover-time { position: absolute; bottom: 22px; transform: translateX(-50%); background: rgba(0,0,0,.8); padding: 3px 8px; font-size: 14px; border-radius: 3px; }
.pl-remaining { font-size: 18px; min-width: 52px; text-align: right; }
.pl-controls { display: flex; align-items: center; justify-content: space-between; }
.pl-left, .pl-right { display: flex; align-items: center; gap: 30px; flex: 1; }
.pl-right { justify-content: flex-end; gap: 40px; }
.pl-title { font-size: 22px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 40%; }
.pl-title b { font-weight: 700; }
.pl-ep { margin-left: 8px; }
.pl-volume { position: relative; }
.pl-volume-pop { position: absolute; bottom: 58px; left: 50%; transform: translateX(-50%); background: #262626; padding: 16px 12px; border-radius: 4px; height: 160px; display: flex; align-items: center; }
.pl-volume-pop input { writing-mode: vertical-lr; direction: rtl; height: 130px; width: 24px; accent-color: var(--red); }
.pl-paused-info { position: absolute; left: 8%; top: 28%; max-width: 46%; z-index: 1; cursor: pointer; }
.pl-paused-info h2 { font-size: 52px; margin: 8px 0; }
.pl-paused-info h3 { font-size: 26px; margin: 0 0 12px; font-weight: 600; }
.pl-paused-info p { font-size: 20px; color: #ddd; line-height: 1.4; }
.pl-panel { position: absolute; right: 30px; bottom: 110px; background: #262626; border-radius: 4px; padding: 20px 24px; min-width: 360px; max-height: 60vh; overflow-y: auto; box-shadow: 0 6px 24px rgba(0,0,0,.6); }
.pl-panel h3 { margin: 0 0 12px; font-size: 22px; }
.episodes-panel ul { list-style: none; margin: 0; padding: 0; }
.episodes-panel li button { display: flex; gap: 14px; width: 100%; background: none; border: 0; padding: 12px 8px; font-size: 18px; text-align: left; border-bottom: 1px solid #3a3a3a; }
.episodes-panel li button.current, .episodes-panel li button:hover { background: #3a3a3a; }
.episodes-panel .n { width: 24px; color: #bbb; }
.episodes-panel .nm { flex: 1; }
.episodes-panel .d { color: #bbb; }
.season-tabs { display: flex; gap: 8px; margin-top: 14px; }
.season-tabs button { background: #3a3a3a; border: 0; padding: 6px 12px; border-radius: 3px; }
.season-tabs button.on { background: #fff; color: #000; }
.subs-panel { display: flex; gap: 50px; }
.subs-panel .opt { font-size: 18px; padding: 6px 0; }
.subs-panel .opt.on { color: #fff; font-weight: 600; }

@media (max-width: 1200px) {
  .primary-nav a { font-size: 15px; padding: 9px 11px; }
  .title-grid { grid-template-columns: repeat(4, 1fr); }
  .landing-header, .landing-promo { padding-left: 40px; padding-right: 40px; }
  .auth-header, .auth-footer { padding-left: 40px; padding-right: 40px; }
}
@media (max-width: 860px) {
  .primary-nav { display: none; }
  .kids-link span { display: none; }
  .title-card, .home .title-card.landscape, .title-card.top10 { width: 42vw; }
  .title-grid { grid-template-columns: repeat(2, 1fr); }
  .tm-info { grid-template-columns: 1fr; }
  .ml-grid { grid-template-columns: 1fr 1fr; }
  .landing-hero h1 { font-size: 36px; }
  .landing-row { flex-direction: column; align-items: center; }
  .landing-row input { width: 90%; }
  .auth-form { width: 100%; }
}

