import { chromium } from 'playwright';
const B = 'http://localhost:5173';
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 } });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', e => errors.push('pageerror ' + e.message));
// login via API
await page.goto(B + '/');
const tok = await page.evaluate(async () => { const r = await fetch('/auth/login', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({email:'demo@netflix.local', password:'netflix123'})}); return (await r.json()).access_token; });
await page.evaluate((t) => { localStorage.setItem('nf_token', t); localStorage.setItem('nf_profile', '2'); }, tok);
const pages = process.argv.slice(2).length ? process.argv.slice(2) : ['/browse','/shows','/movies','/games','/new','/my-list','/browse/languages','/search?q=the','/account','/browse?title=36','/browse?title=2','/watch/36','/profiles','/profiles/manage','/browse/genre/1'];
for (const path of pages) {
  await page.goto(B + path); await page.waitForTimeout(1500);
  const n = await page.locator('button:visible, a:visible, [role=button]:visible, select:visible').count();
  const dead = [];
  for (let i = 0; i < n; i++) {
    await page.goto(B + path); await page.waitForTimeout(900);
    const el = page.locator('button:visible, a:visible, [role=button]:visible, select:visible').nth(i);
    if (!(await el.count())) continue;
    const label = ((await el.getAttribute('aria-label')) || (await el.innerText().catch(()=>'')) || (await el.evaluate(e => e.outerHTML.slice(0,80)))).trim().slice(0,50);
    const tag = await el.evaluate(e => e.tagName);
    if (tag === 'SELECT') continue;
    await page.evaluate(() => { window.__mut = 0; new MutationObserver((m) => { window.__mut += m.length; }).observe(document.body, { subtree: true, childList: true, attributes: true, characterData: true }); });
    let reqs = 0; const onReq = () => reqs++; page.on('request', onReq);
    const url0 = page.url();
    try { await el.click({ timeout: 2000 }); } catch (e) { dead.push(`[unclickable] ${label}`); page.off('request', onReq); continue; }
    await page.waitForTimeout(500);
    const mut = await page.evaluate(() => window.__mut).catch(() => 1);
    page.off('request', onReq);
    if (page.url() === url0 && !mut && !reqs) dead.push(label);
  }
  console.log(path, 'controls', n, 'DEAD:', JSON.stringify(dead));
}
console.log(errors.slice(0,10).join('\n'));
await browser.close();
EOF
cd /tmp/pw && timeout 900 node dead.mjs

